import{_ as s,o as a,c as e,a5 as t}from"./chunks/framework.CyyS6Zdm.js";const g=JSON.parse('{"title":"代码着色","description":"","frontmatter":{},"headers":[],"relativePath":"runtime/code-highlight.md","filePath":"runtime/code-highlight.md","lastUpdated":1787174994000}'),h={name:"runtime/code-highlight.md"};function n(l,i,p,r,o,k){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="代码着色" tabindex="-1">代码着色 <a class="header-anchor" href="#代码着色" aria-label="Permalink to &quot;代码着色&quot;">​</a></h1><p><code>@xihan-ui/code-highlight</code> 是 <code>HighlighterPort</code> 的自研实现：<strong>粗粒度</strong>词法着色，零第三方依赖。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createHighlighter } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@xihan-ui/code-highlight&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> highlighter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createHighlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>把它交给<a href="./../components/code-block">代码块</a>组件的 <code>highlighter</code> prop 即可。组件本身不认任何具体的着色器——它只认这个端口。</p><h2 id="它分得出什么-分不出什么" tabindex="-1">它分得出什么，分不出什么 <a class="header-anchor" href="#它分得出什么-分不出什么" aria-label="Permalink to &quot;它分得出什么，分不出什么&quot;">​</a></h2><p>只分五类：<strong>注释、字符串、数字、关键字、标点</strong>。</p><p>类型名、函数名、属性名这些要靠语法树才分得出的东西<strong>一概不分</strong>——那是 TextMate 语法那一档的活，本实现不追它。所以同一段代码在这里和在编辑器里看不会完全一样，这是预期内的。</p><p>认不出的语言、超长代码一律返回 <code>null</code>，由调用方原样渲染纯文本。<strong>没有着色不等于坏了</strong>，这是设计上的降级路径。</p><h2 id="想要更高精度就换一个" tabindex="-1">想要更高精度就换一个 <a class="header-anchor" href="#想要更高精度就换一个" aria-label="Permalink to &quot;想要更高精度就换一个&quot;">​</a></h2><p><code>highlighter</code> 是一个端口，不是一个实现。把 Shiki、Prism 或别的着色器包成同一个形状接上去，组件侧一个字都不用改：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HighlighterPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  highlight</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">lang</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> readonly</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CodeToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这条端口存在的理由就是这个：<strong>库不替你决定要不要为语法高亮付那几百 kB</strong>。默认给一个够用又不要钱的，想升级随时换。</p><h2 id="为什么不直接内置-shiki" tabindex="-1">为什么不直接内置 Shiki <a class="header-anchor" href="#为什么不直接内置-shiki" aria-label="Permalink to &quot;为什么不直接内置 Shiki&quot;">​</a></h2><p>Shiki 要带 TextMate 语法与主题数据，体积在几百 kB 量级，且需要异步加载。对一个&quot;文档里偶尔出现一段代码&quot;的场景，这个代价不成比例。而对真的在做代码编辑器的人来说，粗粒度着色又肯定不够——两边都不该被库替他们决定。端口是唯一能同时满足两边的形态。</p><h2 id="支持哪些语言" tabindex="-1">支持哪些语言 <a class="header-anchor" href="#支持哪些语言" aria-label="Permalink to &quot;支持哪些语言&quot;">​</a></h2><p><code>langSpecOf(lang)</code> 认得的语言就是支持的。传进去认不出的标注返回 <code>null</code>，代码原样渲染。</p><p>流式场景要配合 <code>complete</code> 用：未闭合的代码随时会变，着色是纯计算但不是免费的，等闭合了再上一次更划算。<a href="./../components/code-block">代码块</a>组件的 <code>highlightWhileStreaming</code> 就是这个开关。</p><h2 id="长度上限" tabindex="-1">长度上限 <a class="header-anchor" href="#长度上限" aria-label="Permalink to &quot;长度上限&quot;">​</a></h2><p>超过 <code>HIGHLIGHT_MAX_LENGTH</code> 的代码直接返回 <code>null</code>。着色是同步的，超长输入会阻塞主线程，与其卡住不如不着色。这个常量是导出的，可以读但改不了——要处理超长代码，那本来就该是 worker 里的活。</p>`,19)])])}const c=s(h,[["render",n]]);export{g as __pageData,c as default};
